        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    /**
     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
     * owner using the same telephone number.
     *
     * @param owner the candidate owner to check
     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
     */
    /**
     * Builds the customer code assigned to a newly created owner, formatted as
     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
     * already registered in the same city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
     *
     * @param owner the owner being created
     * @return the customer code for the owner
     */
    private String customerCode(Owner owner) {
        String city = owner.getCity();
        long existingInCity = this.clinicService.findAllOwners().stream()
            .filter(existing -> Objects.equals(existing.getCity(), city))
            .count();
        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
    }

    /**
     * Determines the canonical spelling of the city for a newly created owner. If another owner
     * already lives in the same city (matched case- and whitespace-insensitively), that owner's exact
     * spelling of the city name is reused so that all owners in a city share a consistent value.
     * Otherwise the supplied city is title-cased (e.g. {@code "new york"} becomes {@code "New York"}).
     *
     * @param city the raw city as supplied when creating the owner, may be {@code null}
     * @return the canonical city spelling, or {@code null} if {@code city} was {@code null}
     */
    private String canonicalCity(String city) {
        if (city == null) {
            return null;
        }
        String normalized = normalize(city);
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (existing.getCity() != null && normalized.equals(normalize(existing.getCity()))) {
                return existing.getCity();
            }
        }
        return titleCase(city);
    }

    /**
     * Title-cases a value by upper-casing the first letter of every whitespace-separated word and
     * lower-casing the rest, collapsing any run of internal whitespace to a single space (e.g.
     * {@code "new  YORK city"} becomes {@code "New York City"}).
     *
     * @param value the value to title-case
     * @return the title-cased value
     */
    private static String titleCase(String value) {
        StringBuilder result = new StringBuilder();
        for (String word : value.strip().split("\\s+")) {
            if (word.isEmpty()) {
                continue;
            }
            if (result.length() > 0) {
                result.append(' ');
            }
            result.append(Character.toUpperCase(word.charAt(0)))
                .append(word.substring(1).toLowerCase(Locale.ROOT));
        }
        return result.toString();
    }

    /**
     * Determines whether the maximum number of owners allowed to be registered on a single day has
     * already been reached. At most 20 owners may be created with today's registration date; once
     * that many exist, further registrations for today are rejected.
     *
     * @return {@code true} if 20 or more owners already have today's registration date
     */
    private boolean isDailyRegistrationLimitReached() {
        LocalDate today = LocalDate.now();
        long registeredToday = this.clinicService.findAllOwners().stream()
            .filter(existing -> today.equals(existing.getRegistrationDate()))
            .count();
        return registeredToday >= 20;
    }

    private boolean isDuplicateOwner(Owner owner) {
        return this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
    }

    /**
     * Normalises a telephone number to digits only by stripping spaces, dashes and parentheses (and
     * any other non-digit characters). This is applied before storing the number and before the
     * telephone-uniqueness check, so that e.g. {@code "(613) 555-0100"} and {@code "6135550100"} are
     * stored identically and treated as the same number.
     *
     * @param telephone the raw telephone number, may be {@code null}
     * @return the digits-only telephone number, or {@code null} if {@code telephone} was {@code null}
     */
    private static String normalizeTelephone(String telephone) {
        if (telephone == null) {
            return null;
        }
        return telephone.replaceAll("[^0-9]", "");
    }

    /**
     * Determines whether the given owner's email address is already used by another owner. An owner
     * without an email address never conflicts. The comparison is case-insensitive and ignores
     * surrounding or repeated whitespace, so e.g. {@code "  John.Smith@Example.com "} and
     * {@code "john.smith@example.com"} are treated as the same address.
     *
     * @param owner the candidate owner to check
     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
     */
    private boolean isDuplicateEmail(Owner owner) {
        String email = normalize(owner.getEmail());
        if (email == null || email.isEmpty()) {
            return false;
        }
        return this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
    }

    /**
     * Normalises a value for case- and whitespace-insensitive duplicate detection: surrounding
     * whitespace is stripped, any run of internal whitespace is collapsed to a single space and all
     * letters are lower-cased. This is what makes {@code "  john   smith "} and {@code "John Smith"}
     * count as the same person (or, for e-mail, the same address) when detecting duplicates.
     *
     * @param value the raw value, may be {@code null}
     * @return the normalised value, or {@code null} if {@code value} was {@code null}
     */
    private static String normalize(String value) {
        if (value == null) {
            return null;
        }
        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

